ORDER BY tree_depth ASC, node_order ASC

WITH RECURSIVE active_path AS (
    SELECT
    ,
    1 AS page_depth
    FROM fin_ex_chat_message_t m
    JOIN fin_ex_chat_session_t s ON s.id = m.session_id
    WHERE m.tenant_id = #{tenantId}
      AND m.user_id = #{userId}
      AND m.session_id = #{sessionId}


      AND m.id = #{pageStartMessageId}


      AND m.id = #{leafMessageId}


      AND m.id = s.current_leaf_message_id


    UNION ALL
    SELECT
    ,
    child.page_depth + 1 AS page_depth
    FROM fin_ex_chat_message_t m
    JOIN active_path child ON child.parent_message_id = m.id
    WHERE m.tenant_id = #{tenantId}
      AND m.user_id = #{userId}
      AND m.session_id = #{sessionId}
      AND child.page_depth < #{fetchLimit}
)
SELECT

FROM active_path
ORDER BY page_depth ASC
LIMIT #{fetchLimit}

