FROM fin_ex_chat_message_t
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND session_id = #{sessionId}
  AND role IN ('user', 'assistant')
ORDER BY node_order ASC, created_at ASC, id ASC

WITH RECURSIVE page_messages AS ( SELECT m.id AS page_message_id, m.parent_message_id, m.role FROM fin_ex_chat_message_t m WHERE m.tenant_id = #{tenantId} AND m.user_id = #{userId} AND m.session_id = #{sessionId} AND m.role IN ('user', 'assistant')
AND m.id IN
#{messageId}
AND 1 = 0
), sibling_candidates AS ( SELECT p.page_message_id, s.id AS candidate_id, s.role AS candidate_role, ROW_NUMBER() OVER ( PARTITION BY p.page_message_id ORDER BY s.node_order ASC, s.created_at ASC, s.id ASC ) AS version_index, COUNT(1) OVER (PARTITION BY p.page_message_id) AS sibling_count, s.locked, s.origin_type, s.edited_from_message_id, s.regenerated_from_message_id, s.created_at, s.tree_depth, s.node_order FROM page_messages p JOIN fin_ex_chat_message_t s ON s.tenant_id = #{tenantId} AND s.user_id = #{userId} AND s.session_id = #{sessionId} AND s.role = p.role AND ( s.parent_message_id = p.parent_message_id OR (s.parent_message_id IS NULL AND p.parent_message_id IS NULL) ) ), version_candidates AS ( SELECT page_message_id, candidate_id, candidate_role, version_index, sibling_count, locked, origin_type, edited_from_message_id, regenerated_from_message_id, created_at, tree_depth, node_order FROM sibling_candidates WHERE sibling_count > 1 ), descendants ( page_message_id, candidate_id, candidate_role, node_id, node_role, tree_depth, node_order, created_at ) AS ( SELECT vc.page_message_id, vc.candidate_id, vc.candidate_role, vc.candidate_id, vc.candidate_role, vc.tree_depth, vc.node_order, vc.created_at FROM version_candidates vc UNION ALL SELECT d.page_message_id, d.candidate_id, d.candidate_role, child.id, child.role, child.tree_depth, child.node_order, child.created_at FROM descendants d JOIN fin_ex_chat_message_t child ON child.tenant_id = #{tenantId} AND child.user_id = #{userId} AND child.session_id = #{sessionId} AND child.parent_message_id = d.node_id AND child.role IN ('user', 'assistant') ), ranked_switches AS ( SELECT d.page_message_id, d.candidate_id, d.node_id, ROW_NUMBER() OVER ( PARTITION BY d.page_message_id, d.candidate_id ORDER BY d.tree_depth DESC, d.node_order DESC, d.created_at DESC, d.node_id DESC ) AS switch_rank FROM descendants d WHERE ( d.candidate_role = 'user' AND d.node_role = 'assistant' ) OR ( d.candidate_role = 'assistant' AND NOT EXISTS ( SELECT 1 FROM fin_ex_chat_message_t visible_child WHERE visible_child.tenant_id = #{tenantId} AND visible_child.user_id = #{userId} AND visible_child.session_id = #{sessionId} AND visible_child.parent_message_id = d.node_id AND visible_child.role IN ('user', 'assistant') ) ) ), best_switches AS ( SELECT page_message_id, candidate_id, node_id FROM ranked_switches WHERE switch_rank = 1 ) SELECT vc.page_message_id, vc.candidate_id AS message_id, vc.candidate_role AS role, vc.version_index AS sibling_index, vc.locked, vc.origin_type, vc.edited_from_message_id, vc.regenerated_from_message_id, vc.created_at, bs.node_id AS switch_leaf_message_id FROM version_candidates vc LEFT JOIN best_switches bs ON bs.page_message_id = vc.page_message_id AND bs.candidate_id = vc.candidate_id ORDER BY vc.page_message_id ASC, vc.version_index ASC

SELECT
FROM ( SELECT , ROW_NUMBER() OVER ( PARTITION BY m.session_id ORDER BY m.node_order ASC, m.created_at ASC, m.id ASC ) AS rn FROM fin_ex_chat_message_t m JOIN fin_ex_chat_session_t s ON s.id = m.session_id AND s.tenant_id = m.tenant_id AND s.user_id = m.user_id WHERE m.tenant_id = #{tenantId} AND m.user_id = #{userId} AND m.role = 'assistant' AND s.status <> 'DELETED'
AND m.session_id IN
#{sessionId}
AND 1 = 0
) ranked WHERE ranked.rn = 1

